cd /app && python3 << 'EOF'
import mujoco
model = mujoco.MjModel.from_xml_path("model_ref.xml")

print("All available options with defaults:")
for attr in sorted(dir(model.opt)):
    if not attr.startswith('_'):
        try:
            val = getattr(model.opt, attr)
            if not callable(val):
                print(f"  {attr}: {val} (type: {type(val).__name__})")
        except:
            pass
EOF
